    siafudb:
      '---\n_schemaVersion: "v1"\nconsistency_model: "eventual"\ncurrentVersion: 1\ndatabase: "SiafuDB (embedded property graph)"\ndescription: "SiafuDB Graph Sync Protocol is the canonical device-to-cloud sync protocol for doctrine v3.5. SiafuDB is a first-party Bundu Foundation embedded property-graph database with CRDT-inspired bidirectional sync. Phase 1 / early-stage as of 2026-05; until SiafuDB Graph Sync ships, Mongo-native RxDB replication is the interim sync implementation."\ndnaRole: "documentation"\ndoctrineVersion: "4.1.0"\nkind: "architecture"\nmodel: "mzizi-dna-helix"\nname: "siafudb"\nnode: 0\nowner: "nyuchi"\nrole: "Sync protocol (canonical) — bidirectional Graph Sync across device, edge, and Pod"\nsort_order: 4\nsovereignty:\n  role: "Sync protocol"\n  license: "Apache-2.0"\n  forkable: true\n  rationale: "Bundu Foundation project — Nyuchi develops, the Foundation governs IP. Apache-2.0 with relicensing legally prevented. First-party and maximally sovereign."\n  governance: "bundu-foundation"\n  technology: "SiafuDB"\n  selfHostable: true\n  sovereigntyRisk: "none"\nstrand: "transcription"\n---\n\n\n',
    "supabase-postgresql":
      '---\n_schemaVersion: "v1"\nconsistency_model: "strict"\ncurrentVersion: 1\ndata_categories:\n- "user-identity"\n- "authentication"\n- "wallet-balances"\n- "transaction-records"\n- "billing"\n- "subscription-state"\n- "relational-roles"\ndatabase: "PostgreSQL"\ndescription: "Open source Firebase alternative built on PostgreSQL. Provides managed Postgres, real-time change subscriptions, row-level security, and REST/GraphQL API. Apache 2.0 licensed and fully self-hostable. Handles data requiring strict consistency — two conflicting versions of a wallet balance are never acceptable. The relational model, foreign keys, and ACID transactions provide the guarantees that money requires."\ndnaRole: "documentation"\ndoctrineVersion: "4.1.0"\nkind: "architecture"\nmodel: "mzizi-dna-helix"\nname: "supabase-postgresql"\nnode: 0\nowner: "nyuchi"\nrole: "Structured, relational, consistent data"\nsort_order: 0\nsovereignty:\n  role: "Relational cloud database"\n  license: "Apache-2.0"\n  forkable: true\n  rationale: "Apache 2.0 licensed, fully self-hostable. If Nyuchi Africa ever needs its own instance on African cloud infrastructure, that option exists."\n  governance: "corporate-open"\n  technology: "Supabase / PostgreSQL"\n  selfHostable: true\n  sovereigntyRisk: "low"\nstrand: "transcription"\n---\n\n\n',
